pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));
        address admin = address(this);

        bool ok;
        try c.setOwner(actor) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.assume(ok);

        vm.prank(actor);
        bool ok2;
        try c.setOwner(newOwner) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(c.owner() == actor);
    }
}
